# [doc = " The configuration used to determine a DFA's start state for a search."] # [doc = ""] # [doc = " A DFA has a single starting state in the typical textbook description. That"] # [doc = " is, it corresponds to the set of all starting states for the NFA that built"] # [doc = " it, along with their espsilon closures. In this crate, however, DFAs have"] # [doc = " many possible start states due to a few factors:"] # [doc = ""] # [doc = " * DFAs support the ability to run either anchored or unanchored searches."] # [doc = " Each type of search needs its own start state. For example, an unanchored"] # [doc = " search requires starting at a state corresponding to a regex with a"] # [doc = " `(?s-u:.)*?` prefix, which will match through anything."] # [doc = " * DFAs also optionally support starting an anchored search for any one"] # [doc = " specific pattern. Each such pattern requires its own start state."] # [doc = " * If a look-behind assertion like `^` or `\\b` is used in the regex, then"] # [doc = " the DFA will need to inspect a single byte immediately before the start of"] # [doc = " the search to choose the correct start state."] # [doc = ""] # [doc = " Indeed, this configuration precisely encapsulates all of the above factors."] # [doc = " The [`Config::anchored`] method sets which kind of anchored search to"] # [doc = " perform while the [`Config::look_behind`] method provides a way to set"] # [doc = " the byte that occurs immediately before the start of the search."] # [doc = ""] # [doc = " Generally speaking, this type is only useful when you want to run searches"] # [doc = " without using an [`Input`]. In particular, an `Input` wants a haystack"] # [doc = " slice, but callers may not have a contiguous sequence of bytes as a"] # [doc = " haystack in all cases. This type provides a lower level of control such"] # [doc = " that callers can provide their own anchored configuration and look-behind"] # [doc = " byte explicitly."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This shows basic usage that permits running a search with a DFA without"] # [doc = " using the `Input` abstraction."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{"] # [doc = "     dfa::{Automaton, dense},"] # [doc = "     util::start,"] # [doc = "     Anchored,"] # [doc = " };"] # [doc = ""] # [doc = " let dfa = dense::DFA::new(r\"(?-u)\\b\\w+\\b\")?;"] # [doc = " let haystack = \"quartz\";"] # [doc = ""] # [doc = " let config = start::Config::new().anchored(Anchored::Yes);"] # [doc = " let mut state = dfa.start_state(&config)?;"] # [doc = " for &b in haystack.as_bytes().iter() {"] # [doc = "     state = dfa.next_state(state, b);"] # [doc = " }"] # [doc = " state = dfa.next_eoi_state(state);"] # [doc = " assert!(dfa.is_match_state(state));"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " This example shows how to correctly run a search that doesn't begin at"] # [doc = " the start of a haystack. Notice how we set the look-behind byte, and as"] # [doc = " a result, the `\\b` assertion does not match."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{"] # [doc = "     dfa::{Automaton, dense},"] # [doc = "     util::start,"] # [doc = "     Anchored,"] # [doc = " };"] # [doc = ""] # [doc = " let dfa = dense::DFA::new(r\"(?-u)\\b\\w+\\b\")?;"] # [doc = " let haystack = \"quartz\";"] # [doc = ""] # [doc = " let config = start::Config::new()"] # [doc = "     .anchored(Anchored::Yes)"] # [doc = "     .look_behind(Some(b'q'));"] # [doc = " let mut state = dfa.start_state(&config)?;"] # [doc = " for &b in haystack.as_bytes().iter().skip(1) {"] # [doc = "     state = dfa.next_state(state, b);"] # [doc = " }"] # [doc = " state = dfa.next_eoi_state(state);"] # [doc = " // No match!"] # [doc = " assert!(!dfa.is_match_state(state));"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " If we had instead not set a look-behind byte, then the DFA would assume"] # [doc = " that it was starting at the beginning of the haystack, and thus `\\b` should"] # [doc = " match. This in turn would result in erroneously reporting a match:"] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{"] # [doc = "     dfa::{Automaton, dense},"] # [doc = "     util::start,"] # [doc = "     Anchored,"] # [doc = " };"] # [doc = ""] # [doc = " let dfa = dense::DFA::new(r\"(?-u)\\b\\w+\\b\")?;"] # [doc = " let haystack = \"quartz\";"] # [doc = ""] # [doc = " // Whoops, forgot the look-behind byte..."] # [doc = " let config = start::Config::new().anchored(Anchored::Yes);"] # [doc = " let mut state = dfa.start_state(&config)?;"] # [doc = " for &b in haystack.as_bytes().iter().skip(1) {"] # [doc = "     state = dfa.next_state(state, b);"] # [doc = " }"] # [doc = " state = dfa.next_eoi_state(state);"] # [doc = " // And now we get a match unexpectedly."] # [doc = " assert!(dfa.is_match_state(state));"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [derive (Clone , Debug)] pub struct Config { look_behind : Option < u8 > , anchored : Anchored , }
